-- Schema migrations: CREATE/ALTER/DROP with IF [NOT] EXISTS, indexes, constraints
CREATE DATABASE IF NOT EXISTS shop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL, name VARCHAR(100) DEFAULT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uk_email (email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, total DECIMAL(12, 2) NOT NULL DEFAULT 0.00, status ENUM('new', 'paid', 'shipped', 'cancelled') NOT NULL DEFAULT 'new', note TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY idx_user (user_id), KEY idx_status_created (status, created_at), CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (order_id BIGINT UNSIGNED NOT NULL, product_id INT NOT NULL, qty SMALLINT NOT NULL DEFAULT 1, price DECIMAL(10, 2) NOT NULL, PRIMARY KEY (order_id, product_id), CONSTRAINT chk_qty CHECK (qty > 0));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(64) NOT NULL, action VARCHAR(32) NOT NULL, payload JSON, at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
CREATE TABLE IF NOT EXISTS events (id BIGINT NOT NULL, happened_on DATE NOT NULL, body TEXT, PRIMARY KEY (id, happened_on)) PARTITION BY RANGE (YEAR(happened_on)) (PARTITION p2024 VALUES LESS THAN (2025), PARTITION p2025 VALUES LESS THAN (2026), PARTITION pmax VALUES LESS THAN MAXVALUE);
CREATE TABLE IF NOT EXISTS people (id INT PRIMARY KEY, first_name VARCHAR(50), last_name VARCHAR(50), full_name VARCHAR(101) AS (CONCAT(first_name, ' ', last_name)) VIRTUAL, name_len INT AS (CHAR_LENGTH(first_name)) PERSISTENT);
CREATE TABLE IF NOT EXISTS temp_copy LIKE users;
CREATE TABLE IF NOT EXISTS user_emails AS SELECT id, email FROM users WHERE email IS NOT NULL;
CREATE TEMPORARY TABLE IF NOT EXISTS tmp_ids (id INT PRIMARY KEY);
CREATE OR REPLACE TABLE scratch (a INT, b VARCHAR(10));
CREATE INDEX IF NOT EXISTS idx_orders_total ON orders (total);
CREATE UNIQUE INDEX IF NOT EXISTS uk_users_name ON users (name, email);
CREATE FULLTEXT INDEX IF NOT EXISTS ft_note ON orders (note);
CREATE INDEX idx_prefix ON users (email(20));
CREATE OR REPLACE VIEW v_active_users AS SELECT id, email FROM users WHERE name IS NOT NULL;
CREATE VIEW IF NOT EXISTS v_order_totals AS SELECT user_id, SUM(total) AS total FROM orders GROUP BY user_id;
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone VARCHAR(32) NULL AFTER name;
ALTER TABLE users ADD COLUMN last_login DATETIME NULL, ADD COLUMN login_count INT NOT NULL DEFAULT 0;
ALTER TABLE users MODIFY COLUMN name VARCHAR(200) NOT NULL DEFAULT '';
ALTER TABLE users CHANGE COLUMN phone mobile VARCHAR(40) NULL;
ALTER TABLE users DROP COLUMN IF EXISTS mobile;
ALTER TABLE users ADD INDEX IF NOT EXISTS idx_name (name);
ALTER TABLE users DROP INDEX IF EXISTS idx_name;
ALTER TABLE orders ADD CONSTRAINT fk_o_u FOREIGN KEY (user_id) REFERENCES users (id);
ALTER TABLE orders DROP FOREIGN KEY fk_o_u;
ALTER TABLE orders ADD PRIMARY KEY (id);
ALTER TABLE orders ENGINE=InnoDB, ALGORITHM=INPLACE, LOCK=NONE;
ALTER TABLE orders RENAME TO orders_old;
ALTER TABLE orders ALTER COLUMN status SET DEFAULT 'new';
ALTER TABLE orders ALTER COLUMN note DROP DEFAULT;
ALTER ONLINE TABLE orders ADD COLUMN flag TINYINT(1) NOT NULL DEFAULT 0;
RENAME TABLE orders_old TO orders_archive, scratch TO scratch_old;
TRUNCATE TABLE audit_log;
DROP TABLE IF EXISTS scratch_old, temp_copy;
DROP VIEW IF EXISTS v_active_users;
DROP INDEX IF EXISTS idx_orders_total ON orders;
DROP DATABASE IF EXISTS shop_old;
CREATE TRIGGER trg_users_bu BEFORE UPDATE ON users FOR EACH ROW SET NEW.updated_at = NOW();
CREATE OR REPLACE TRIGGER trg_orders_ai AFTER INSERT ON orders FOR EACH ROW INSERT INTO audit_log (actor, action) VALUES ('system', 'order');
DROP TRIGGER IF EXISTS trg_users_bu;
CREATE USER IF NOT EXISTS 'app'@'%' IDENTIFIED BY 'secret';
GRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'app'@'%';
REVOKE DELETE ON shop.* FROM 'app'@'%';
FLUSH PRIVILEGES;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET @a := 1;
SET SESSION sql_mode = 'STRICT_ALL_TABLES';
USE shop;
ANALYZE TABLE orders;
OPTIMIZE TABLE orders;
LOCK TABLES orders WRITE, users READ;
UNLOCK TABLES;
